steps.solution:
#include <iostream>
using namespace std;

int main() {
    char drone;
    int metric;
    cin >> drone >> metric;

    switch (drone) {
        case 'S':
            if (metric > 20) {
                cout << "SIGMA: GROUNDED" << endl;
            } else {
                cout << "SIGMA: AIRBORNE" << endl;
            }
            break;
        case 'D':
            if (metric > 50) {
                cout << "DELTA: SHELTERED" << endl;
            } else {
                cout << "DELTA: SCANNING" << endl;
            }
            break;
        default:
            cout << "DRONE: UNRECOGNIZED" << endl;
            break;
    }

    return 0;
}

